				timelineValidationData,
				boqValidationData,
				techSpecsValidationData,
				assetListValidationData,
				vendorMakeValidationData,
				nfaValidationData
			};
		}
		return null;
	}, [modelData]);

	// Rejection Flow: Returns PR back to Stage 01 (OA/ARC Check)
	const handleRejectInit = useCallback(() => {
		setShowRejectModal(true);
	}, []);
	const handleConfirmReject = useCallback(reasonText => {
		const commentVal = (reasonText || rejectReason || '').trim();
		if (!commentVal) return;
		setShowRejectModal(false);
		setRejectReason('');
		if (window.appsmith?.updateModel) {
			window.appsmith.updateModel({
				rejectionComment: commentVal
			});
		}
		const trigger = () => {
			if (window.appsmith?.triggerEvent) {
				window.appsmith.triggerEvent('onReject', {
					rejectionComment: commentVal
				});
			}
		};
		if (window.appsmith?.updateModel) {
			Promise.resolve(window.appsmith.updateModel({
				rejectionComment: commentVal
			})).then(() => setTimeout(trigger, 50)).catch(() => setTimeout(trigger, 50));
		} else {
			trigger();
		}
	}, [rejectReason]);

	// Accept Flow: Enables Approve & Advance Stage button
	const handleAcceptInit = useCallback(() => {
    if (window.appsmith?.triggerEvent) {
      window.appsmith.triggerEvent("onAccept");
    }
  }, []);
	const handleConfirmAccept = useCallback(() => {
		setShowAcceptModal(false);
		// Upon accepting: Reject PR & Accept PR become disabled, Approve & Advance Stage is ENABLED!
		setWfState({
			canRerunValidation: false,
			canReject: false,
			canAccept: false,
			canApprove: true
		});
		if (window.appsmith?.updateModel) {
			window.appsmith.updateModel({
				isAccepted: true,
				canAdvance: true
			});
		}
		const trigger = () => {
			if (window.appsmith?.triggerEvent) {
				window.appsmith.triggerEvent('onAccept', {
					consistencyData
				});
			}
		};
		if (window.appsmith?.updateModel) {
			Promise.resolve(window.appsmith.updateModel({
				isAccepted: true,
				canAdvance: true
			})).then(() => setTimeout(trigger, 50)).catch(() => setTimeout(trigger, 50));
		} else {
			trigger();
		}
	}, [consistencyData]);

	// Approve & Advance Stage Flow: Advances to Stage 03 (Vendor Recommendation)
	const handleApproveAdvance = useCallback(() => {
		if (window.appsmith?.updateModel) {
			window.appsmith.updateModel({
				selectedStageId: 'vendor_recommendation',
				transitionMode: 'view'
			});
		}
		const trigger = () => {
			if (window.appsmith?.triggerEvent) {
				window.appsmith.triggerEvent('onApproveAdvance', {
					consistencyData
				});
			}
		};
		if (window.appsmith?.updateModel) {
			Promise.resolve(window.appsmith.updateModel({
				selectedStageId: 'vendor_recommendation',
				transitionMode: 'view'
			})).then(() => setTimeout(trigger, 50)).catch(() => setTimeout(trigger, 50));
		} else {
			trigger();
		}
	}, [consistencyData]);
	return React.createElement('div', {
		className: 'cc-widget-container'
	}, React.createElement(RejectModal, {
		isOpen: showRejectModal,
		reason: rejectReason,
		onReasonChange: setRejectReason,
		onCancel: () => {
			setShowRejectModal(false);
			setRejectReason('');
		},
		onConfirm: handleConfirmReject
	}), React.createElement(AcceptModal, {
		isOpen: false,
		onCancel: () => setShowAcceptModal(false),
		onConfirm: handleConfirmAccept
	}), React.createElement(ConsistencyWorkspace, {
		data: consistencyData,
		wfState: wfState,
		onRejectInit: handleRejectInit,
		onAcceptInit: handleAcceptInit,
		onApprove: handleApproveAdvance,
		showFooter: showFooter
	}));
}
appsmith.onReady(() => {
	ReactDOM.render(React.createElement(CustomConsistencyCheckHub, null), document.getElementById('root'));
});
